// Minimal ERC721 that calls back into C during safeTransferFrom to observe feeRate during initialize
contract ReentrantERC721 {
    address public owner;
    constructor() { owner = msg.sender; }

    // mimic ERC721.ownerOf and safeTransferFrom behaviour required by C
    mapping(uint256 => address) public _ownerOf;

    function mint(uint256 id, address to) public {
        _ownerOf[id] = to;
    }

    function ownerOf(uint256 id) external view returns (address) {
        return _ownerOf[id];
    }

    // safeTransferFrom called by Factory.create -> C.initialize flow in original system; here we simulate C calling into NFT
    // We implement safeTransferFrom(from,to,id) and during that call we perform a call into the target C to read feeRate()
    function safeTransferFrom(address from, address to, uint256 id) external {
        // transfer to the new owner
        _ownerOf[id] = to;
        // if the recipient is a contract C, try to call onERC721Received to emulate ERC721TokenReceiver behaviour
        // But more importantly, if 'to' is the C being initialized, we attempt to read feeRate() to observe intermediate state.
        // We perform a low-level staticcall to feeRate() selector.
        // feeRate() selector = bytes4(keccak256("feeRate()"))
        if (isContract(to)) {
            // try to call feeRate() on the recipient; ignore success/failure
            (bool success, bytes memory ret) = to.staticcall(abi.encodeWithSignature("feeRate()"));
            // store result in a slot so it is observable (no external storage available here), but we instead emit an event
            if (success && ret.length >= 32) {
                uint256 observed = abi.decode(ret, (uint256));
                Observed(observed);
            } else {
                Observed(type(uint256).max);
            }

            // also try to call onERC721Received to satisfy safeTransferFrom expectations
            // ignore return
            try ERC721TokenReceiver(to).onERC721Received(msg.sender, from, id, "") returns (bytes4) {
            } catch {}
        }
    }

    function isContract(address addr) internal view returns (bool) {
        uint256 size;
        assembly { size := extcodesize(addr) }
        return size > 0;
    }

    event Observed(uint256 v);
}

// Minimal interface matching the receiver used in C
abstract contract ERC721TokenReceiver {
    function onERC721Received(address, address, uint256, bytes calldata) external virtual returns (bytes4) {
        return ERC721TokenReceiver.onERC721Received.selector;
    }
}

