// Minimal adversarial ERC721 which reenters into C during its onERC721Received
contract ReentrantERC721Token {
    address public target;
    mapping(uint256 => address) public ownerOf;

    constructor(address _target) {
        target = _target;
    }

    function setReentryTarget(address _t) external {
        target = _t;
    }

    function mint(address to, uint256 id) external {
        ownerOf[id] = to;
    }

    // emulate ERC721 safeTransferFrom by calling receiver
    function safeTransferFrom(address from, address to, uint256 id) external {
        require(ownerOf[id] == from, "NOT_OWNER");
        ownerOf[id] = to;
        // if recipient is a contract that implements onERC721Received, call it
        // Our recipient in test will be the C contract; call its public view price() to observe feeRate during init
        if (isContract(to)) {
