            (bool success, ) = to.call(abi.encodeWithSelector(bytes4(keccak256("onERC721Received(address,address,uint256,bytes)")), msg.sender, from, id, ""));
            // ignore success
            success;
        }
    }

    // minimal ownerOf
    function balanceOf(address) external pure returns (uint256) { return 1; }

    // helper
    function isContract(address account) internal view returns (bool) {
        uint256 size;
        assembly { size := extcodesize(account) }
        return size > 0;
    }

    // expose ERC721Receiver selector to route to C's onERC721Received (which C inherits from ERC721TokenReceiver)
    fallback() external {}
}
